let state={step:0,done:[],notes:{}},tab=0;try{state={...state,...JSON.parse(localStorage.getItem('trace-review')||'{}')}}catch{}let $=s=>document.querySelector(s),esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');function persist(){localStorage.setItem('trace-review',JSON.stringify(state))}function go(i){state.step=i;persist();render()}function render(){let d=data[state.step];$('#steps').innerHTML=data.map((x,i)=>`<button class="step ${i===state.step?'active':''}" data-step="${i}"><span class="num">${state.done.includes(i)?'✓':i+1}</span><span>${x.title}<small>${x.file.split('/').at(-1)}</small></span></button>`).join('');$('#route').innerHTML=data.map((x,i)=>`<button data-step="${i}" class="${i===state.step?'active':''}">${state.done.includes(i)?'✓ ':''}${x.title}</button>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(+b.dataset.step));files();$('#focus').textContent=d.focus;$('#reason').textContent=d.reason;$('#path').textContent=d.file;$('#symbol').textContent=d.symbol;$('#code').innerHTML=d.lines.map((s,i)=>`<div class="line ${s[0]==='+'?'added':s[0]==='-'?'removed':''}"><b>${i+12}</b>${esc(s)}</div>`).join('');$('#count').textContent=`${state.done.length} из 4 шагов проверено`;$('#bar').style.width=state.done.length*25+'%';$('#next').textContent=state.done.length===4?'Ревью завершено ✓':state.step===3?'Завершить ревью ✓':'Проверено, дальше →';$('#note').value=state.notes[state.step]||'';$('#notes').textContent='';contexts()}
function files(){let q=$('#search').value.toLowerCase();$('#files').innerHTML=data.map((d,i)=>d.file.toLowerCase().includes(q)?`<button class="step file ${state.step===i?'selected':''}" data-file="${i}">⌘ ${d.file}</button>`:'').join('')||'<small>Файлы не найдены</small>';document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>go(+b.dataset.file))}
function contexts(){let labels=['Контракт','Вызовы','Тесты'];$('#tabs').innerHTML=labels.map((x,i)=>`<button data-tab="${i}" class="${i===tab?'active':''}">${x}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=+b.dataset.tab;contexts()});let indexes=tab===0?[0]:tab===1?[1,2]:[3];$('#contexts').innerHTML=indexes.map(i=>`<details class="context" open><summary>${data[i].file}<br><small>${i===state.step?'Текущий фрагмент':'Связь с '+data[state.step].symbol}</small></summary><pre>${esc(data[i].lines.filter(l=>l[0]!=='-').map(l=>l.slice(1)).join('\n'))}</pre></details>`).join('')}
$('#next').onclick=()=>{if(!state.done.includes(state.step))state.done.push(state.step);if(state.step<3)state.step++;persist();render()};$('#search').oninput=files;$('#save').onclick=()=>{state.notes[state.step]=$('#note').value;persist();$('#notes').className='saved';$('#notes').textContent='Заметка сохранена для шага «'+data[state.step].title+'»'};$('#showcontext').onclick=()=>{document.querySelector('.right').scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector('[data-tab]').focus()};$('#reset').onclick=()=>{if(confirm('Сбросить прогресс и заметки демо?')){state={step:0,done:[],notes:{}};persist();render()}};render();
